    """Extract forecast data from soup."""
    forecasts = []
    for wr in fcast.find_all("div", {"class": "daily-wrapper"}):
        forecast = {}

        date = wr.find("h2", {"class": "date"})
        forecast["Date"] = (
            date.find("span").text.strip() + " " + date.find_all("span")[1].text.strip()
        )
        temp = wr.find("div", {"class": "temp"})
